def process(load_water, quincy_revere_marine) -> pd.DataFrame:
    # Filter water testing for Enterococci at relevant beaches
    beaches = quincy_revere_marine['Beach Name'].tolist()
    df = load_water[
        (load_water['Beach Name'].isin(beaches)) &
        (load_water['Organism'] == 'Enterococci')
    ].copy()
    df['Sample Date'] = pd.to_datetime(df['Sample Date'])
    return df[['Community', 'Beach Name', 'Sample Date', 'Indicator Level']].sort_values('Sample Date')

def load() -> pd.DataFrame:
    import csv
    # Read raw lines to check if Indicator Level has < or > signs
    rows = []
    with open('data/environment/input/water-body-testing-2023.csv', 'r') as f:
        reader = csv.reader(f)
        header = next(reader)
        rows.append(header)
        for i, row in enumerate(reader):
            if i < 5:
                rows.append(row)
    result = pd.DataFrame(rows[1:], columns=rows[0])
    # Also check if there's a raw text column with < or > 
    # Read all data and search for < or > in any field
    df = pd.read_csv('data/environment/input/water-body-testing-2023.csv')
    # Check all string columns for < or > 
    found = {}
    for col in df.columns:
        if df[col].dtype == object:
            mask = df[col].str.contains('<|>', na=False)
            if mask.any():
                found[col] = df[col][mask].value_counts().head(5).to_dict()

    summary_rows = [{'column': k, 'values': str(v)} for k, v in found.items()]
    if not summary_rows:
        summary_rows = [{'column': 'none', 'values': 'No < or > found in string columns'}]
    return pd.DataFrame(summary_rows)
